<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body { font-family: 'Inter', system-ui, -apple-system, sans-serif; background: #0A0A0A; color: #FFFFFF; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
  ::selection { background: rgba(59, 130, 246, 0.3); color: #fff; }

  /* Custom scrollbar */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: #0A0A0A; }
  ::-webkit-scrollbar-thumb { background: #333; border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: #555; }

  /* Hero carousel */
  .hero-slide { opacity: 0; transition: opacity 0.7s ease-in-out; position: absolute; inset: 0; }
  .hero-slide.active { opacity: 1; }

  /* Team card transitions */
  .team-card { transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); }
  .team-card.entering { animation: cardEnter 0.5s ease-out forwards; }
  .team-card.exiting { animation: cardExit 0.3s ease-in forwards; }
  @keyframes cardEnter {
    from { opacity: 0; transform: translateY(20px) scale(0.95); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  @keyframes cardExit {
    from { opacity: 1; transform: translateY(0) scale(1); }
    to { opacity: 0; transform: translateY(-10px) scale(0.95); }
  }

  /* Region tab active */
  .region-tab { transition: all 0.3s ease; position: relative; }
  .region-tab::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%) scaleX(0);
    width: 100%;
    height: 2px;
    background: #3B82F6;
    transition: transform 0.3s ease;
  }
  .region-tab.active { color: #3B82F6; }
  .region-tab.active::after { transform: translateX(-50%) scaleX(1); }

  /* Work showcase horizontal scroll */
  .work-scroll { scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; }
  .work-scroll::-webkit-scrollbar { height: 4px; }
  .work-scroll::-webkit-scrollbar-track { background: transparent; }
  .work-scroll::-webkit-scrollbar-thumb { background: #333; border-radius: 2px; }
  .work-card { scroll-snap-align: start; }

  /* Lang dropdown */
  .lang-dropdown { opacity: 0; visibility: hidden; transform: translateY(-8px); transition: all 0.2s ease; }
  .lang-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }

  /* Cookie banner */
  .cookie-banner { transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1); }
  .cookie-banner.visible { transform: translateY(0); }

  /* Mobile menu */
  .mobile-menu { opacity: 0; visibility: hidden; transform: translateX(100%); transition: all 0.35s ease; }
  .mobile-menu.open { opacity: 1; visibility: visible; transform: translateX(0); }

  /* Nav scroll effect */
  .nav-blur { background: rgba(10, 10, 10, 0.85); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); }

  /* Gradient overlays */
  .gradient-overlay { background: linear-gradient(to top, rgba(10,10,10,1) 0%, rgba(10,10,10,0) 100%); }
  .gradient-hero-overlay { background: linear-gradient(to right, rgba(10,10,10,0.92) 0%, rgba(10,10,10,0.4) 100%); }
  .gradient-card { background: linear-gradient(135deg, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0.01) 100%); }

  /* Hero progress bar */
  .hero-progress { transition: width 5s linear; }

  /* Accordion-line style for mobile insight cards */
  .insight-border { border: 1px solid rgba(255,255,255,0.08); transition: border-color 0.3s ease; }
  .insight-border:hover { border-color: rgba(59,130,246,0.4); }

  /* Team photo placeholder */
  .team-photo { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }

  /* Principle number */
  .principle-num { font-feature-settings: "tnum"; font-variant-numeric: tabular-nums; }

  /* Pulse dot */
  .pulse-dot { animation: pulse 2s infinite; }
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.4; }
  }
</style>
</head>
