<script>
// ── Team Data ──
const teamData = {
  'north-america': [
    {
      name: 'Denice Alvarez',
      title: 'Office Manager',
      office: 'New York',
      quote: 'As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers.',
      gradient: 'from-blue-900/50 to-indigo-900/50',
      initials: 'DA'
    },
    {
      name: 'Marco Bellini',
      title: 'Design Director',
      office: 'San Francisco',
      quote: 'Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make.',
      gradient: 'from-orange-900/50 to-red-900/50',
      initials: 'MB'
    }
  ],
  'asia': [
    {
      name: 'Priya Mehta',
      title: 'Studio Head',
      office: 'Bangalore',
      quote: 'We bring your brand vision to life, with transformative ideas and impactful marketing campaigns fueled by creativity and enthusiasm.',
      gradient: 'from-pink-900/50 to-rose-900/50',
      initials: 'PM'
    },
    {
      name: 'Thierry Lam',
      title: 'Design Lead',
      office: 'Singapore',
      quote: 'Good design is multifaceted. It impacts functionality, aesthetics, strategy, environment, business and so much more. Great design is seamless.',
      gradient: 'from-teal-900/50 to-emerald-900/50',
      initials: 'TL'
    }
  ],
  'europe': [
    {
      name: 'Gavin Hartley',
      title: 'Managing Director',
      office: 'London',
      quote: "It's my job to make sure we innovate and push the boundaries when collaborating with brands to create inspiring customer experiences that deliver great business results.",
      gradient: 'from-purple-900/50 to-violet-900/50',
      initials: 'GH'
    },
    {
      name: 'Francesca Terzi',
      title: 'Design Director',
      office: 'Munich',
      quote: 'At Leap Studio, I am constantly amazed by the talent I am surrounded with. We love to dream big and bring those dreams to life.',
      gradient: 'from-amber-900/50 to-yellow-900/50',
      initials: 'FT'
    }
  ],
  'oceania': [
    {
      name: 'Jacintha Soo Ho',
      title: 'Senior Manager, CX Transformation',
      office: 'Melbourne',
      quote: 'I love helping clients see beyond their assumptions and showing them opportunities they haven\'t thought of before.',
      gradient: 'from-cyan-900/50 to-blue-900/50',
      initials: 'JS'
    }
  ]
};

let currentRegion = 'north-america';
let currentTeamPage = 0;

function renderTeamCards(region) {
  const container = document.getElementById('teamCards');
  const members = teamData[region];
  const cardsPerPage = window.innerWidth < 768 ? 1 : 2;
  const totalPages = Math.ceil(members.length / cardsPerPage);

  // Clamp page
  if (currentTeamPage >= totalPages) currentTeamPage = 0;

  const start = currentTeamPage * cardsPerPage;
  const visibleMembers = members.slice(start, start + cardsPerPage);

  container.innerHTML = visibleMembers.map(member => `
    <div class="team-card gradient-card rounded-3xl border border-white/5 overflow-hidden group">
      <div class="p-8 md:p-10">
        <div class="flex items-start space-x-6">
          <div class="w-20 h-20 md:w-24 md:h-24 rounded-2xl bg-gradient-to-br ${member.gradient} flex items-center justify-center flex-shrink-0">
            <span class="text-2xl md:text-3xl font-bold text-white/60">${member.initials}</span>
          </div>
          <div class="flex-1 min-w-0">
            <h3 class="text-xl md:text-2xl font-bold mb-1">${member.name}</h3>
            <p class="text-sm text-blue-400 font-medium mb-1">${member.title}</p>
            <p class="text-xs text-gray-500">${member.office}</p>
          </div>
        </div>
        <blockquote class="mt-6 text-gray-400 leading-relaxed text-sm md:text-base italic border-l-2 border-white/10 pl-4">
          "${member.quote}"
        </blockquote>
        <a href="#contact" class="inline-flex items-center space-x-2 mt-6 text-sm text-blue-400 font-medium hover:text-blue-300 transition-colors group">
          <span>Contact Leap Studio ${member.office.split(',')[0]}</span>
          <svg class="w-3.5 h-3.5 group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M5 12h14M12 5l7 7-7 7" stroke-width="2"/></svg>
        </a>
      </div>
    </div>
  `).join('');

  // Update mobile dots
  updateTeamDots(totalPages);
}

function updateTeamDots(totalPages) {
  const dotsContainer = document.getElementById('teamMobileDots');
  if (totalPages <= 1) { dotsContainer.innerHTML = ''; return; }
  dotsContainer.innerHTML = Array.from({ length: totalPages }, (_, i) =>
    `<button class="w-2 h-2 rounded-full transition-all duration-300 ${i === currentTeamPage ? 'bg-blue-400 w-5' : 'bg-white/20'}" data-page="${i}"></button>`
  ).join('');
}

// ── Region Tab Clicks ──
document.querySelectorAll('.region-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.region-tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    currentRegion = tab.dataset.region;
    currentTeamPage = 0;
    renderTeamCards(currentRegion);
  });
});

// ── Mobile Team Dots ──
document.getElementById('teamMobileDots').addEventListener('click', (e) => {
  const dot = e.target.closest('button');
  if (!dot) return;
  currentTeamPage = parseInt(dot.dataset.page);
  renderTeamCards(currentRegion);
});

// ── Hero Carousel ──
let currentHeroSlide = 0;
const totalHeroSlides = 5;
let heroInterval;
const SLIDE_DURATION = 5000;

function goToHeroSlide(index) {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('#heroDots button');

  slides.forEach(s => s.classList.remove('active'));
  dots.forEach(d => { d.classList.remove('active-dot'); d.style.width = '10px'; d.style.backgroundColor = 'rgba(255,255,255,0.3)'; });

  currentHeroSlide = ((index % totalHeroSlides) + totalHeroSlides) % totalHeroSlides;
  slides[currentHeroSlide].classList.add('active');

  const activeDot = dots[currentHeroSlide];
  activeDot.classList.add('active-dot');
  activeDot.style.width = '28px';
  activeDot.style.backgroundColor = 'rgba(255,255,255,0.8)';
}

function nextHeroSlide() { goToHeroSlide(currentHeroSlide + 1); }
function prevHeroSlide() { goToHeroSlide(currentHeroSlide - 1); }

function resetHeroInterval() {
  clearInterval(heroInterval);
  heroInterval = setInterval(nextHeroSlide, SLIDE_DURATION);
}

document.getElementById('heroNext').addEventListener('click', () => { nextHeroSlide(); resetHeroInterval(); });
document.getElementById('heroPrev').addEventListener('click', () => { prevHeroSlide(); resetHeroInterval(); });

document.querySelectorAll('#heroDots button').forEach(dot => {
  dot.addEventListener('click', () => {
    goToHeroSlide(parseInt(dot.dataset.dot));
    resetHeroInterval();
  });
});

// Touch/swipe for hero
let heroTouchStart = 0;
const heroSection = document.getElementById('hero');
heroSection.addEventListener('touchstart', e => { heroTouchStart = e.touches[0].clientX; });
heroSection.addEventListener('touchend', e => {
  const diff = heroTouchStart - e.changedTouches[0].clientX;
  if (Math.abs(diff) > 50) {
    diff > 0 ? nextHeroSlide() : prevHeroSlide();
    resetHeroInterval();
  }
});

// Start hero autoplay
heroInterval = setInterval(nextHeroSlide, SLIDE_DURATION);

// ── Language Dropdown ──
const langBtn = document.getElementById('langBtn');
const langDropdown = document.getElementById('langDropdown');
const langChevron = document.getElementById('langChevron');

langBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  const isOpen = langDropdown.classList.contains('open');
  langDropdown.classList.toggle('open');
  langChevron.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';
});

langDropdown.querySelectorAll('button').forEach(btn => {
  btn.addEventListener('click', () => {
    const lang = btn.dataset.lang;
    langBtn.querySelector('span').textContent = lang;

    // Update active state
    langDropdown.querySelectorAll('button').forEach(b => {
      b.classList.remove('text-blue-400');
      b.classList.add('text-gray-400');
    });
    btn.classList.remove('text-gray-400');
    btn.classList.add('text-blue-400');

    langDropdown.classList.remove('open');
    langChevron.style.transform = 'rotate(0deg)';
  });
});

document.addEventListener('click', () => {
  langDropdown.classList.remove('open');
  langChevron.style.transform = 'rotate(0deg)';
});

// ── Mobile Menu ──
const menuToggle = document.getElementById('menuToggle');
const mobileMenu = document.getElementById('mobileMenu');
const menuIcon = document.getElementById('menuIcon');
let menuOpen = false;

menuToggle.addEventListener('click', () => {
  menuOpen = !menuOpen;
  mobileMenu.classList.toggle('open');
  menuIcon.innerHTML = menuOpen
    ? '<path stroke-width="2" d="M6 6l12 12M18 6L6 18"/>'
    : '<path stroke-width="2" d="M4 6h16M4 12h16M4 18h16"/>';
  document.body.style.overflow = menuOpen ? 'hidden' : '';
});

document.querySelectorAll('.mobile-link').forEach(link => {
  link.addEventListener('click', () => {
    menuOpen = false;
    mobileMenu.classList.remove('open');
    menuIcon.innerHTML = '<path stroke-width="2" d="M4 6h16M4 12h16M4 18h16"/>';
    document.body.style.overflow = '';
  });
});

// ── Cookie Consent ──
const cookieBanner = document.getElementById('cookieBanner');

// Show banner after a short delay
setTimeout(() => {
  cookieBanner.classList.add('visible');
}, 1500);

document.getElementById('cookieAccept').addEventListener('click', () => {
  cookieBanner.classList.remove('visible');
  document.cookie = "leap_cookies=accepted; max-age=31536000; path=/";
});

document.getElementById('cookieDecline').addEventListener('click', () => {
  cookieBanner.classList.remove('visible');
  document.cookie = "leap_cookies=declined; max-age=31536000; path=/";
});

document.getElementById('cookieSettings').addEventListener('click', () => {
  cookieBanner.classList.remove('visible');
});

// Don't show if already set
if (document.cookie.includes('leap_cookies')) {
  cookieBanner.style.display = 'none';
}

// ── Nav scroll effect ──
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  if (window.scrollY > 50) {
    navbar.classList.add('nav-blur');
  } else {
    navbar.classList.remove('nav-blur');
  }
});

// ── Smooth scroll for anchor links ──
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function(e) {
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      e.preventDefault();
      const offset = 80;
      const top = target.getBoundingClientRect().top + window.pageYOffset - offset;
      window.scrollTo({ top, behavior: 'smooth' });
    }
  });
});

// ── Touch/swipe for work scroll ──
const workScroll = document.getElementById('workScroll');
let workTouchStart = 0;
let workScrollLeft = 0;

workScroll.addEventListener('touchstart', e => {
  workTouchStart = e.touches[0].clientX;
  workScrollLeft = workScroll.scrollLeft;
});

workScroll.addEventListener('touchmove', e => {
  const diff = workTouchStart - e.touches[0].clientX;
  workScroll.scrollLeft = workScrollLeft + diff;
});

// ── Keyboard nav for hero ──
document.addEventListener('keydown', e => {
  if (e.key === 'ArrowRight') { nextHeroSlide(); resetHeroInterval(); }
  if (e.key === 'ArrowLeft') { prevHeroSlide(); resetHeroInterval(); }
});

// ── Resize handler for team cards ──
let resizeDebounce;
window.addEventListener('resize', () => {
  clearTimeout(resizeDebounce);
  resizeDebounce = setTimeout(() => {
    currentTeamPage = 0;
    renderTeamCards(currentRegion);
  }, 250);
});

// ── Initial render ──
renderTeamCards('north-america');
goToHeroSlide(0);

// ── Intersection Observer for section animations ──
const observerOptions = { threshold: 0.1, rootMargin: '0px 0px -40px 0px' };
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.style.opacity = '1';
      entry.target.style.transform = 'translateY(0)';
    }
  });
}, observerOptions);

document.querySelectorAll('section').forEach(section => {
  section.style.opacity = '0';
  section.style.transform = 'translateY(20px)';
  section.style.transition = 'opacity 0.6s ease-out, transform 0.6s ease-out';
  observer.observe(section);
});

// Fade in hero immediately
document.getElementById('hero').style.opacity = '1';
document.getElementById('hero').style.transform = 'translateY(0)';
</script>
